import pg from "pg";
import { drizzle } from "drizzle-orm/node-postgres";
import dotenv from "dotenv";
var Pool, databaseUrl, isRemoteDb, poolConfig, pool, db;
var init_db = __esm({
  "server/db.ts"() {
    "use strict";
    init_schema();
    ({ Pool } = pg);
    dotenv.config();
    databaseUrl = process.env.DATABASE_URL;
    isRemoteDb = databaseUrl && !databaseUrl.includes("localhost") && !databaseUrl.includes("127.0.0.1");
    poolConfig = isRemoteDb ? {
      connectionString: databaseUrl,
      max: 20,
      idleTimeoutMillis: 3e4,
      connectionTimeoutMillis: 5e3,
      ssl: { rejectUnauthorized: false }
    } : {
      user: process.env.PGUSER || "versoair",
      password: process.env.PGPASSWORD || "versoair2025",
      host: process.env.PGHOST || "localhost",
      port: parseInt(process.env.PGPORT || "5432"),
      database: process.env.PGDATABASE || "versoair_business_intelligence",
      max: 20,
      idleTimeoutMillis: 3e4,
      connectionTimeoutMillis: 2e3
    };
    console.log(
      "\u{1F50C} [DB] Using",
      isRemoteDb ? "DATABASE_URL (remote)" : "local PG* env vars"
    );
    pool = new Pool(poolConfig);
    db = drizzle(pool, { schema: schema_exports });
    pool.on("connect", () => {
      console.log(
        "\u2705 Connected to PostgreSQL database: versoair_business_intelligence"
      );
    });
    pool.on("error", (err) => {
      console.error("\u274C PostgreSQL pool error:", err);
    });
  }
});

// server/services/email-service.ts
import nodemailer from "nodemailer";
function getAppUrl() {
  if (process.env.APP_PUBLIC_URL)
    return process.env.APP_PUBLIC_URL.replace(/\/$/, "");
  if (process.env.RENDER_EXTERNAL_URL)
    return process.env.RENDER_EXTERNAL_URL.replace(/\/$/, "");
  const cors = (process.env.CORS_ORIGIN || "").split(",").map((u) => u.trim());
  const external = cors.find(
    (u) => !u.includes("localhost") && !u.includes("127.0.0.1")
  );
  if (external) return external.replace(/\/$/, "");
  return `http://localhost:${process.env.PORT || 5003}`;
}
function initializeEmailTransporter() {
  const host = process.env.SMTP_HOST || "smtp.gmail.com";
  const port = parseInt(process.env.SMTP_PORT || "587", 10);
  const user = process.env.SMTP_USER;
  const pass = process.env.SMTP_PASS;
  const from = process.env.SMTP_FROM || "noreply@versoair.com";
  if (!user || !pass) {
    console.warn(
      "[EMAIL] SMTP credentials not configured. Email notifications disabled."
    );
    return null;
  }
  transporter = nodemailer.createTransport({
    host,
    port,
    secure: port === 465,
    // true for 465, false for other ports
    auth: {
      user,
      pass
    },
    from
  });
  console.log(`[EMAIL] Transporter initialized. Sending from: ${from}`);
  return transporter;
}
